type Section = "overview" | "review" | "evidence" | "return" | "records" | "operations" | "activity" | "settings" | "team" | "filing" | "firm";
const sections: Section[] = ["overview", "review", "evidence", "return", "records", "operations", "activity", "settings", "team", "filing", "firm"];
const navigation = [
 {id:"review",label:"Review",icon:ClipboardCheck}, {id:"return",label:"Return",icon:FileText},
 {id:"evidence",label:"Evidence",icon:FolderOpen}, {id:"team",label:"Team",icon:Users},
 {id:"filing",label:"Filing & next year",icon:CalendarClock},
] as const;
const subscribeMobile = (listener:()=>void) => { const media=window.matchMedia("(max-width:700px)");media.addEventListener("change",listener);return()=>media.removeEventListener("change",listener); };
const mobileSnapshot = () => window.matchMedia("(max-width:700px)").matches;
const desktopSnapshot = () => false;
function primarySection(section: Section) { return ["overview","operations"].includes(section) ? "review" : section === "records" ? "return" : section === "activity" ? "team" : section === "firm" ? "settings" : section; }
const formNames:Record<string,string> = { F1040:"Individual return", SchC:"Business", SchA:"Itemized deductions", SchE:"Rentals & pass-throughs", SchD:"Capital gains", F8949:"Sales detail", F540NR:"California return", F8606:"IRA basis", F7203:"S corporation basis" };
