 const explorerLines=version==="v3"?(data?.lines||[]):versionLines;const lines=explorerLines.filter((l:RecordData)=>(!search||`${l.key} ${l.label}`.toLowerCase().includes(search.toLowerCase()))&&(form==="all"||l.form===form));
